<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('admin');
$db=Database::connection();$service=new RegistrationService($db);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');
 try{$controller=new RegistrationController($service);if($action==='cancel')$controller->cancel(current_user_id(),$id,true);else $controller->decide(current_user_id(),$id,$action,post_string('note',500));flash('success','Registration updated.');}
 catch(DomainException $e){flash('danger',$e->getMessage());}
 catch(Throwable $e){error_log('Admin registration action error: '.$e->getMessage());flash('danger','Registration could not be updated.');}
 redirect('admin/registrations.php');
}
$status=(string)($_GET['status']??'');$q=trim((string)($_GET['q']??''));$sql="SELECT r.*,s.full_name,s.register_number,c.code,c.title,t.name term_name FROM registrations r JOIN students s ON s.id=r.student_id JOIN courses c ON c.id=r.course_id JOIN academic_terms t ON t.id=r.term_id WHERE 1=1";$params=[];if(in_array($status,['pending','approved','rejected','cancelled'],true)){$sql.=' AND r.status=?';$params[]=$status;}if($q!==''){$sql.=' AND (s.full_name LIKE ? OR s.register_number LIKE ? OR c.code LIKE ? OR c.title LIKE ?)';$n='%'.$q.'%';array_push($params,$n,$n,$n,$n);}$sql.=' ORDER BY FIELD(r.status,"pending","approved","rejected","cancelled"),r.requested_at DESC LIMIT 500';$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
page_start('Manage registrations','admin/registrations.php');
?>
<div class="content-width"><?php page_title('Registration requests','Review enrollment requests and notify students of decisions.'); ?>
<div class="panel mb-3"><form class="row g-2"><div class="col-md-6"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search student or course"></div><div class="col-md-4"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['pending','approved','rejected','cancelled'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select></div><div class="col-md-2 d-grid"><button class="btn btn-outline-primary">Filter</button></div></form></div>
<div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Course</th><th>Term</th><th>Requested</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="small text-muted"><?= e($r['register_number']) ?></div></td><td><?= e($r['code'].' · '.$r['title']) ?></td><td><?= e($r['term_name']) ?></td><td><?= e(date('M j, Y',strtotime($r['requested_at']))) ?></td><td><?= status_badge($r['status']) ?><?php if($r['decision_note']): ?><div class="small text-muted"><?= e($r['decision_note']) ?></div><?php endif; ?></td><td class="table-actions"><?php if($r['status']==='pending'): foreach(['approved'=>'Approve','rejected'=>'Reject'] as $action=>$label): ?><form class="d-inline" method="post" data-confirm-submit="<?= e($label) ?> this request?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="note" value=""><button class="btn btn-sm btn-outline-<?= $action==='approved'?'success':'danger' ?>"><?= e($label) ?></button></form><?php endforeach; endif; ?><?php if(in_array($r['status'],['pending','approved'],true)): ?><form class="d-inline" method="post" data-confirm-submit="Cancel registration and release its seat?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="cancel"><button class="btn btn-sm btn-outline-secondary">Cancel</button></form><?php endif; ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6"><div class="empty-state"><h3>No registrations match</h3></div></td></tr><?php endif; ?></tbody></table></div></div></div>
<?php page_end(); ?>
